public class Main {
    public static void main(String[] args) {
        Hinh h = new Vuong(4);
        System.out.println(h.dienTich());
    }
}

interface Hinh {
    double dienTich();
}

class Vuong implements Hinh {
    double canh;
    Vuong(double c) { canh = c; }
    public double dienTich() { return canh * canh; }
}
